		private Preservation beforeAdvance(List<PendingPublication> publications) {
			boolean writes = publications.stream().anyMatch(batch -> batch.mutated || !batch.events.isEmpty());
			boolean namespaces = publications.stream().anyMatch(batch -> hasNamespaceChanges(batch.evidence));
			List<Borrower> borrowers = writes ? publicationGroup.lockBorrowers(namespaces) : List.of();
			try {
				Map<Borrower, List<SnapshotWriteEvent>> undo = new IdentityHashMap<>();
				for (Borrower borrower : borrowers) {
					List<SnapshotWriteEvent> effects = new ArrayList<>();
					for (PendingPublication batch : publications) {
						if (borrower.participant() == batch.participant) {
							effects.add(SnapshotWriteEvent.inverse(batch.evidence, borrower.context().dataset()));
						} else {
							try (Changeset affected = emptyChangeset()) {
								copyNamespaces(batch.evidence, affected);
								batch.promotions.getOrDefault(borrower.participant(), Set.of())
										.forEach(affected::deprecate);
								effects.add(SnapshotWriteEvent.inverse(affected, borrower.context().dataset()));
							}
						}
					}
					undo.put(borrower, effects);
				}
				borrowers.forEach(borrower -> borrower.context().preserveIterators());
				return new Preservation(borrowers, undo, Map.of());
			} catch (RuntimeException | Error failure) {
				SnapshotResources.closeAll(failure, borrowers);
				throw failure;
			}
		}

		private final class Preservation implements SailClosable {
			private final List<Borrower> borrowers;
			private final Map<Borrower, List<SnapshotWriteEvent>> undo;
			private final Map<SnapshotValidationSupport, Set<Statement>> promotions;

			Preservation(List<Borrower> borrowers, Map<Borrower, List<SnapshotWriteEvent>> undo,
					Map<SnapshotValidationSupport, Set<Statement>> promotions) {
				this.borrowers = borrowers;
				this.undo = undo;
				this.promotions = promotions;
			}

			void accepted() {
				promotions.forEach((participant, statements) -> pending().promotions
						.computeIfAbsent(participant, ignored -> new HashSet<>())
						.addAll(statements));
				if (publicationGroup.sharedTransaction) {
					promotions.forEach(
							(participant, statements) -> statements.forEach(pendingState(participant)::deprecate));
				}
			}

			void applied() {
				for (Borrower borrower : borrowers) {
					undo.getOrDefault(borrower, List.of()).forEach(borrower.context()::applyInverse);
				}
			}

			@Override
			public void close() {
				SnapshotResources.closeAll(borrowers);
			}
		}

		private void mutate(Consumer<Changeset> operation, Runnable publication) {
			prepare();
			lifecycle.lock();
			try {
				checkOpen();
				lockPublication();
				try (Preservation preserved = beforeMutation(operation)) {
					try {
						publication.run();
					} catch (RuntimeException | Error failure) {
						try {
							preserved.applied();
						} catch (RuntimeException | Error cleanup) {
							failure.addSuppressed(cleanup);
						}
						throw failure;
					}
					preserved.applied();
					PendingPublication batch = pending();
					batch.mutated = true;
					operation.accept(batch.evidence);
					if (publicationGroup.sharedTransaction) {
						operation.accept(pendingState(SnapshotValidationSupport.this));
						batch.groupOwned = true;
						publicationGroup.pending.add(batch);
					}
					preserved.accepted();
				} finally {
					publicationLock.unlock();
				}
			} finally {
				lifecycle.unlock();
			}
		}

